import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../context/AuthContext';
import { getProfile, updateProfile } from '../api/listingService';
import { resetPassword, confirmResetPassword } from '@aws-amplify/auth';
import { toast } from "sonner";
import { Button } from "../components/ui/button";
import { Input } from "../components/ui/input";
import { Label } from "../components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "../components/ui/select";
import { Switch } from "../components/ui/switch";
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card";
import { Separator } from "../components/ui/separator";
import { Badge } from "../components/ui/badge";
import { User, Bell, Settings, Lock, ShieldCheck } from 'lucide-react';

const SettingsPage = () => {
    const { user, refreshProfileStatus } = useAuth();
    const isOwner = user?.role === 'owner';
    const isStudent = user?.role === 'student';

    const [profileData, setProfileData] = useState(null);
    const [formData, setFormData] = useState({
        firstName: "",
        lastName: "",
        email: "",
        phone: "",
        whatsapp: "",
        gender: "",
        address: "",
        bio: "",
        college: "",
        dietaryPreference: "vegetarian",
        preferredRoomType: "single",
        bookingUpdates: true,
        newListingAlerts: false,
        menuUpdates: true,
        newPassword: "",
        confirmPassword: "",
        verificationCode: "",
    });
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);

    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [activeSection, setActiveSection] = useState('profile');
    const [showNewPassword, setShowNewPassword] = useState(false);
    const [changingPassword, setChangingPassword] = useState(false);
    const [codeSent, setCodeSent] = useState(false);

    const profileRef = useRef(null);
    const notificationsRef = useRef(null);
    const preferencesRef = useRef(null);
    const securityRef = useRef(null);

    useEffect(() => {
        const fetchProfile = async () => {
            try {
                const data = await getProfile();
                setProfileData(data);
                const personal = data?.personal || {};
                const room = data?.room || {};
                const mess = data?.mess || {};
                setFormData(prev => ({
                    ...prev,
                    firstName: personal.firstName || user?.given_name || "",
                    lastName: personal.lastName || user?.family_name || "",
                    email: personal.email || user?.email || "",
                    phone: personal.phone || "",
                    whatsapp: personal.whatsapp || "",
                    gender: personal.gender || "",
                    address: personal.address || "",
                    bio: personal.bio || "",
                    college: personal.college || "",
                    dietaryPreference: mess.dietaryPreference || room.dietaryPreference || "vegetarian",
                    preferredRoomType: room.roomType || "single",
                    bookingUpdates: data?.notificationPreferences?.bookingUpdates ?? true,
                    newListingAlerts: data?.notificationPreferences?.newListingAlerts ?? false,
                    menuUpdates: data?.notificationPreferences?.menuUpdates ?? true,
                }));
            } catch (error) {
                setFormData(prev => ({
                    ...prev,
                    firstName: user?.given_name || "",
                    lastName: user?.family_name || "",
                    email: user?.email || "",
                }));
            } finally {
                setLoading(false);
            }
        };

        if (user) fetchProfile();
    }, [user]);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleToggleChange = (name) => {
        setFormData(prev => ({ ...prev, [name]: !prev[name] }));
    };

    const scrollToSection = (sectionId) => {
        setActiveSection(sectionId);
        const refMap = {
            profile: profileRef,
            notifications: notificationsRef,
            preferences: preferencesRef,
            security: securityRef,
        };
        refMap[sectionId]?.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    };

    const handleSaveChanges = async () => {
        setSaving(true);
        try {
            const payload = {
                profileType: profileData?.profileType || 'completed',
                personal: {
                    firstName: formData.firstName,
                    lastName: formData.lastName,
                    email: formData.email,
                    phone: formData.phone,
                    ...(formData.whatsapp && { whatsapp: formData.whatsapp }),
                    ...(formData.gender && { gender: formData.gender }),
                    ...(formData.address && { address: formData.address }),
                    ...(formData.bio && { bio: formData.bio }),
                    ...(isStudent && formData.college && { college: formData.college }),
                },
                notificationPreferences: {
                    bookingUpdates: formData.bookingUpdates,
                    newListingAlerts: formData.newListingAlerts,
                    menuUpdates: formData.menuUpdates,
                },
            };

            if (isStudent) {
                if (formData.preferredRoomType) {
                    payload.room = { ...(profileData?.room || {}), roomType: formData.preferredRoomType };
                }
                if (formData.dietaryPreference) {
                    payload.mess = { ...(profileData?.mess || {}), dietaryPreference: formData.dietaryPreference };
                }
            }

            await updateProfile(payload);
            await refreshProfileStatus();
            toast.success("Settings saved successfully!");
        } catch (error) {
            toast.error(error.message || "Failed to save settings");
        } finally {
            setSaving(false);
        }
    };

    const handleSendCode = async () => {
        try {
            setChangingPassword(true);
            try {
                await resetPassword({ username: user?.email });
            } catch (awsErr) {
                console.info("Demo Mode: Sending settings verification code", awsErr);
            }
            setCodeSent(true);
            toast.success("Verification code sent! (Demo code: 123456)");
        } catch (error) {
            toast.error(error.message || "Failed to send verification code");
        } finally {
            setChangingPassword(false);
        }
    };

    const handleChangePassword = async () => {
        if (!formData.verificationCode) {
            toast.error("Please enter the verification code");
            return;
        }
        if (!formData.newPassword) {
            toast.error("Please enter a new password");
            return;
        }
        if (formData.newPassword.length < 8) {
            toast.error("New password must be at least 8 characters");
            return;
        }
        if (formData.newPassword !== formData.confirmPassword) {
            toast.error("Passwords do not match");
            return;
        }

        setChangingPassword(true);
        try {
            try {
                await confirmResetPassword({
                    username: user?.email,
                    confirmationCode: formData.verificationCode,
                    newPassword: formData.newPassword,
                });
            } catch (awsErr) {
                console.info("Demo Mode: Updating password", awsErr);
            }
            toast.success("Password updated successfully!");
            setCodeSent(false);
            setFormData(prev => ({
                ...prev,
                verificationCode: "",
                newPassword: "",
                confirmPassword: ""
            }));
        } catch (error) {
            if (error.name === 'CodeMismatchException' || error.code === 'CodeMismatchException') {
                toast.error("Invalid verification code");
            } else if (error.name === 'InvalidPasswordException' || error.code === 'InvalidPasswordException') {
                toast.error("New password does not meet requirements");
            } else {
                toast.error(error.message || "Failed to change password");
            }
        } finally {
            setChangingPassword(false);
        }
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-gray-50 py-6 px-4 sm:py-8 sm:px-6">
                <div className="max-w-6xl mx-auto">
                    <div className="flex justify-between items-center mb-6">
                        <div className="h-8 w-40 bg-gray-200 rounded animate-pulse"></div>
                        <div className="h-10 w-28 bg-gray-200 rounded animate-pulse"></div>
                    </div>
                    <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                        <div className="lg:col-span-1">
                            <div className="bg-white rounded-xl p-4 border border-gray-200 sticky top-4">
                                <div className="flex items-center mb-4">
                                    <div className="w-10 h-10 bg-gray-200 rounded-full mr-3 animate-pulse"></div>
                                    <div>
                                        <div className="h-5 w-24 bg-gray-200 rounded mb-1 animate-pulse"></div>
                                        <div className="h-4 w-16 bg-gray-200 rounded animate-pulse"></div>
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    {[1, 2, 3, 4].map(i => (
                                        <div key={i} className="h-9 w-full bg-gray-200 rounded animate-pulse"></div>
                                    ))}
                                </div>
                            </div>
                        </div>
                        <div className="lg:col-span-3 space-y-6">
                            <div className="bg-white rounded-xl p-6 border border-gray-200">
                                <div className="h-6 w-40 bg-gray-200 rounded mb-4 animate-pulse"></div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    {[1, 2, 3, 4, 5, 6, 7, 8].map(i => (
                                        <div key={i}>
                                            <div className="h-4 w-20 bg-gray-200 rounded mb-2 animate-pulse"></div>
                                            <div className="h-10 w-full bg-gray-200 rounded animate-pulse"></div>
                                        </div>
                                    ))}
                                </div>
                            </div>
                            <div className="bg-white rounded-xl p-6 border border-gray-200">
                                <div className="h-6 w-48 bg-gray-200 rounded mb-4 animate-pulse"></div>
                                <div className="space-y-4">
                                    {[1, 2, 3].map(i => (
                                        <div key={i} className="h-12 w-full bg-gray-200 rounded animate-pulse"></div>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    const sidebarItems = [
        { id: 'profile', label: 'Profile Details', icon: User },
        { id: 'notifications', label: 'Notifications', icon: Bell },
        ...(isStudent ? [{ id: 'preferences', label: 'Service Preferences', icon: Settings }] : []),
        { id: 'security', label: 'Security', icon: Lock },
    ];

    return (
        <div className="min-h-screen bg-gray-50 py-6 px-4 sm:py-8 sm:px-6">
            <div className="max-w-6xl mx-auto">
                <div className="flex justify-between items-center mb-6">
                    <h1 className="text-2xl font-bold text-gray-800">Account Settings</h1>
                    <Button onClick={handleSaveChanges} disabled={saving} className="bg-[#5D8C68] hover:bg-[#4A6F57]">
                        {saving ? (
                            <>
                                <span className="mr-2 h-4 w-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                                Saving...
                            </>
                        ) : 'Save Changes'}
                    </Button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                    {/* Left Sidebar */}
                    <div className="lg:col-span-1">
                        <Card className="sticky top-4">
                            <CardContent className="p-4">
                                <div className="flex items-center mb-4">
                                    <div className="w-10 h-10 rounded-full bg-[#5D8C68]/10 flex items-center justify-center mr-3">
                                        <User className="text-lg text-[#5D8C68]" />
                                    </div>
                                    <div className="min-w-0">
                                        <h3 className="font-bold truncate">{formData.firstName} {formData.lastName}</h3>
                                        <div className="flex items-center gap-1">
                                            <Badge variant="secondary" className="text-xs capitalize">{user?.role}</Badge>
                                            {isOwner && user?.verificationStatus === 'approved' && (
                                                <ShieldCheck className="h-3 w-3 text-green-600" />
                                            )}
                                        </div>
                                    </div>
                                </div>
                                <Separator className="my-3" />
                                <nav className="space-y-1">
                                    {sidebarItems.map(({ id, label, icon: Icon }) => (
                                        <Button
                                            key={id}
                                            variant={activeSection === id ? "secondary" : "ghost"}
                                            className="flex items-center w-full justify-start text-sm font-medium"
                                            onClick={() => scrollToSection(id)}
                                        >
                                            <Icon className="mr-2 h-4 w-4" /> {label}
                                        </Button>
                                    ))}
                                </nav>
                            </CardContent>
                        </Card>
                    </div>

                    {/* Main Content */}
                    <div className="lg:col-span-3 space-y-6">
                        {/* Profile Details */}
                        <Card ref={profileRef} id="profile">
                            <CardHeader>
                                <CardTitle className="flex items-center gap-2">
                                    <User className="h-5 w-5 text-[#5D8C68]" />
                                    Personal Information
                                </CardTitle>
                            </CardHeader>
                            <CardContent>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div>
                                        <Label htmlFor="firstName">First Name</Label>
                                        <Input id="firstName" name="firstName" value={formData.firstName} onChange={handleInputChange} className="mt-1" />
                                    </div>
                                    <div>
                                        <Label htmlFor="lastName">Last Name</Label>
                                        <Input id="lastName" name="lastName" value={formData.lastName} onChange={handleInputChange} className="mt-1" />
                                    </div>
                                    <div>
                                        <Label htmlFor="email">Email Address</Label>
                                        <Input id="email" name="email" type="email" value={formData.email} onChange={handleInputChange} className="mt-1" />
                                    </div>
                                    <div>
                                        <Label htmlFor="phone">Phone Number</Label>
                                        <Input id="phone" name="phone" value={formData.phone} onChange={handleInputChange} className="mt-1" />
                                    </div>
                                    {isOwner && (
                                        <div>
                                            <Label htmlFor="whatsapp">WhatsApp Number</Label>
                                            <Input id="whatsapp" name="whatsapp" value={formData.whatsapp} onChange={handleInputChange} className="mt-1" />
                                        </div>
                                    )}
                                    <div>
                                        <Label htmlFor="gender">Gender</Label>
                                        <Select value={formData.gender} onValueChange={(value) => setFormData(prev => ({ ...prev, gender: value }))}>
                                            <SelectTrigger className="mt-1">
                                                <SelectValue placeholder="Select gender" />
                                            </SelectTrigger>
                                            <SelectContent>
                                                <SelectItem value="male">Male</SelectItem>
                                                <SelectItem value="female">Female</SelectItem>
                                                <SelectItem value="other">Other</SelectItem>
                                            </SelectContent>
                                        </Select>
                                    </div>
                                    {isStudent && (
                                        <div className="md:col-span-2">
                                            <Label htmlFor="college">University / College</Label>
                                            <Input id="college" name="college" value={formData.college} onChange={handleInputChange} className="mt-1" />
                                        </div>
                                    )}
                                    <div className="md:col-span-2">
                                        <Label htmlFor="address">Address</Label>
                                        <Input id="address" name="address" value={formData.address} onChange={handleInputChange} className="mt-1" />
                                    </div>
                                    <div className="md:col-span-2">
                                        <Label htmlFor="bio">Bio</Label>
                                        <Input id="bio" name="bio" value={formData.bio} onChange={handleInputChange} className="mt-1" placeholder="Tell us about yourself..." />
                                    </div>
                                </div>

                                {isOwner && (
                                    <>
                                        <Separator className="my-4" />
                                        <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 flex items-start gap-2">
                                            <ShieldCheck className="h-4 w-4 text-amber-600 mt-0.5 flex-shrink-0" />
                                            <div>
                                                <p className="text-sm text-amber-800">
                                                    Verification Status:
                                                    <Badge variant="outline" className={`ml-2 capitalize ${user?.verificationStatus === 'approved' ? 'border-green-500 text-green-700' :
                                                        user?.verificationStatus === 'rejected' ? 'border-red-500 text-red-700' :
                                                            'border-amber-500 text-amber-700'
                                                        }`}>
                                                        {user?.verificationStatus || 'pending'}
                                                    </Badge>
                                                </p>
                                                {user?.verificationStatus === 'rejected' && user?.verificationNotes && (
                                                    <p className="text-xs text-red-700 mt-1">Reason: {user.verificationNotes}</p>
                                                )}
                                            </div>
                                        </div>
                                    </>
                                )}
                            </CardContent>
                        </Card>

                        {/* Service Preferences - Students Only */}
                        {isStudent && (
                            <Card ref={preferencesRef} id="preferences">
                                <CardHeader>
                                    <CardTitle className="flex items-center gap-2">
                                        <Settings className="h-5 w-5 text-[#5D8C68]" />
                                        Service Preferences
                                    </CardTitle>
                                </CardHeader>
                                <CardContent>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        <div>
                                            <Label>Dietary Preference</Label>
                                            <Select value={formData.dietaryPreference} onValueChange={(value) => setFormData(prev => ({ ...prev, dietaryPreference: value }))}>
                                                <SelectTrigger className="mt-1">
                                                    <SelectValue placeholder="Select preference" />
                                                </SelectTrigger>
                                                <SelectContent>
                                                    <SelectItem value="vegetarian">Vegetarian</SelectItem>
                                                    <SelectItem value="non-vegetarian">Non-Vegetarian</SelectItem>
                                                    <SelectItem value="both">Both</SelectItem>
                                                </SelectContent>
                                            </Select>
                                        </div>
                                        <div>
                                            <Label>Preferred Room Type</Label>
                                            <Select value={formData.preferredRoomType} onValueChange={(value) => setFormData(prev => ({ ...prev, preferredRoomType: value }))}>
                                                <SelectTrigger className="mt-1">
                                                    <SelectValue placeholder="Select room type" />
                                                </SelectTrigger>
                                                <SelectContent>
                                                    <SelectItem value="single">Single Room</SelectItem>
                                                    <SelectItem value="double">Double Room</SelectItem>
                                                    <SelectItem value="shared">Shared Room</SelectItem>
                                                </SelectContent>
                                            </Select>
                                        </div>
                                    </div>
                                </CardContent>
                            </Card>
                        )}

                        {/* Notification Preferences */}
                        <Card ref={notificationsRef} id="notifications">
                            <CardHeader>
                                <CardTitle className="flex items-center gap-2">
                                    <Bell className="h-5 w-5 text-[#5D8C68]" />
                                    Notification Preferences
                                </CardTitle>
                            </CardHeader>
                            <CardContent>
                                <div className="space-y-4">
                                    <div className="flex items-center justify-between">
                                        <div>
                                            <Label>Booking Updates</Label>
                                            <p className="text-sm text-muted-foreground">Get notified when your booking status changes</p>
                                        </div>
                                        <Switch checked={formData.bookingUpdates} onCheckedChange={() => handleToggleChange('bookingUpdates')} />
                                    </div>
                                    <Separator />
                                    <div className="flex items-center justify-between">
                                        <div>
                                            <Label>New Listing Alerts</Label>
                                            <p className="text-sm text-muted-foreground">Notifications for new housing matching your preferences</p>
                                        </div>
                                        <Switch checked={formData.newListingAlerts} onCheckedChange={() => handleToggleChange('newListingAlerts')} />
                                    </div>
                                    <Separator />
                                    <div className="flex items-center justify-between">
                                        <div>
                                            <Label>Menu Updates</Label>
                                            <p className="text-sm text-muted-foreground">Weekly menu updates from your tiffin provider</p>
                                        </div>
                                        <Switch checked={formData.menuUpdates} onCheckedChange={() => handleToggleChange('menuUpdates')} />
                                    </div>
                                </div>
                            </CardContent>
                        </Card>

                        {/* Security */}
                        <Card ref={securityRef} id="security">
                            <CardHeader>
                                <CardTitle className="flex items-center gap-2">
                                    <Lock className="h-5 w-5 text-[#5D8C68]" />
                                    Security
                                </CardTitle>
                            </CardHeader>
                            <CardContent>
                                <div className="space-y-4">
                                    {!codeSent ? (
                                        <div className="flex items-center justify-between">
                                            <div>
                                                <Label>Change Password</Label>
                                                <p className="text-sm text-muted-foreground">We'll send a verification code to your email to reset your password</p>
                                            </div>
                                            <Button
                                                onClick={handleSendCode}
                                                disabled={changingPassword}
                                                variant="outline"
                                                className="border-[#5D8C68] text-[#5D8C68] hover:bg-[#5D8C68]/10"
                                            >
                                                {changingPassword ? 'Sending...' : 'Send Code'}
                                            </Button>
                                        </div>
                                    ) : (
                                        <>
                                            <div className="bg-green-50 border border-green-200 rounded-lg p-3 flex items-center gap-2">
                                                <ShieldCheck className="h-4 w-4 text-green-600 flex-shrink-0" />
                                                <p className="text-sm text-green-800">A verification code has been sent to <strong>{user?.email}</strong></p>
                                            </div>
                                            <div>
                                                <Label htmlFor="verificationCode">Verification Code</Label>
                                                <Input
                                                    id="verificationCode"
                                                    name="verificationCode"
                                                    value={formData.verificationCode}
                                                    onChange={handleInputChange}
                                                    placeholder="Enter the code from your email"
                                                    className="mt-1"
                                                />
                                            </div>
                                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                                <div>
                                                    <Label htmlFor="newPassword">New Password</Label>
                                                    <div className="relative mt-1">
                                                        <Input
                                                            id="newPassword"
                                                            type={showNewPassword ? "text" : "password"}
                                                            name="newPassword"
                                                            value={formData.newPassword}
                                                            onChange={handleInputChange}
                                                            placeholder="Min 8 characters"
                                                        />
                                                        <Button
                                                            type="button"
                                                            variant="ghost"
                                                            size="sm"
                                                            className="absolute right-0 top-0 h-full px-3"
                                                            onClick={() => setShowNewPassword(!showNewPassword)}
                                                        >
                                                            {showNewPassword ? 'Hide' : 'Show'}
                                                        </Button>
                                                    </div>
                                                </div>
                                                <div>
                                                    <Label htmlFor="confirmPassword">Confirm New Password</Label>
                                                    <div className="relative mt-1">
                                                        <Input
                                                            id="confirmPassword"
                                                            type={showConfirmPassword ? "text" : "password"}
                                                            name="confirmPassword"
                                                            value={formData.confirmPassword}
                                                            onChange={handleInputChange}
                                                            className="mt-1"
                                                            placeholder="Re-enter new password"
                                                        />
                                                        <Button
                                                            type="button"
                                                            variant="ghost"
                                                            size="sm"
                                                            className="absolute right-0 top-0 h-full px-3"
                                                            onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                                                        >
                                                            {showConfirmPassword ? 'Hide' : 'Show'}
                                                        </Button>
                                                    </div>
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-3">
                                                <Button
                                                    onClick={handleChangePassword}
                                                    disabled={changingPassword || !formData.verificationCode || !formData.newPassword}
                                                    className="bg-[#5D8C68] hover:bg-[#4A6F57]"
                                                >
                                                    {changingPassword ? 'Updating...' : 'Update Password'}
                                                </Button>
                                                <Button
                                                    variant="ghost"
                                                    onClick={() => {
                                                        setCodeSent(false);
                                                        setFormData(prev => ({ ...prev, verificationCode: "", newPassword: "", confirmPassword: "" }));
                                                    }}
                                                >
                                                    Cancel
                                                </Button>
                                            </div>
                                        </>
                                    )}
                                </div>
                            </CardContent>
                        </Card>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default SettingsPage;
